// Dữ liệu vào: header bí mật và identity kỹ thuật của một bài Progress Log.
// Việc chính: xác thực nguồn gửi, kiểm tra ID và tự tính lại bốn lớp identity.
// Kết quả: gói sạch để đọc đúng lớp, học viên và buổi trên Portal.
// Khi lỗi: dừng trước khi gọi Portal; execution chỉ hiện mã lỗi chung.

const request = $input.first()?.json ?? {};
const headers = request.headers ?? {};
const supplied = String(headers['x-learning-attendance-sync'] ?? headers['X-Learning-Attendance-Sync'] ?? '');
const expectedSecret = String($vars.TERM_TEST_ERP_SYNC_SECRET ?? '');
function sameSecret(left, right) {
  if (!left || !right || left.length !== right.length) return false;
  let difference = 0;
  for (let index = 0; index < left.length; index += 1) difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return difference === 0;
}
if (!sameSecret(supplied, expectedSecret)) throw new Error('ATTENDANCE_SYNC_UNAUTHORIZED');

const body = request.body ?? {};
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const teacherOverride = body.schemaVersion === 'LearningPortalAttendanceOverrideJobV1';
const checkpointSource = body.schemaVersion === 'LearningPortalAttendanceCheckpointJobV1';
const recordId = String(teacherOverride ? body.attendanceEventId ?? '' : checkpointSource ? body.checkpointSubmissionId ?? '' : body.submissionId ?? '').toLowerCase();
const assignmentId = String(body.assignmentId ?? '').toLowerCase();
const studentRef = String(body.studentRef ?? '').toLowerCase();
const classId = String(body.classId ?? '');
const studentId = String(body.studentId ?? '');
const sessionNumber = Number(body.sessionNumber);
const commit = body.commit === true;
if (!['LearningPortalAttendanceJobV1', 'LearningPortalAttendanceOverrideJobV1', 'LearningPortalAttendanceCheckpointJobV1'].includes(body.schemaVersion) || body.attendanceStatus !== 'PRESENT') throw new Error('ATTENDANCE_SYNC_INVALID_SCHEMA');
if (![recordId, assignmentId, studentRef].every(value => uuidPattern.test(value))) throw new Error('ATTENDANCE_SYNC_INVALID_UUID');
if (!/^\d+$/.test(classId) || !/^\d+$/.test(studentId) || !Number.isInteger(sessionNumber) || sessionNumber < 1 || sessionNumber > 100) throw new Error('ATTENDANCE_SYNC_INVALID_TARGET');
// Nguồn nộp phần có mã riêng; không giả thành bài nộp cuối hoặc điều chỉnh giảng viên.
const prefix = teacherOverride ? 'portal-attendance-override' : checkpointSource ? 'portal-attendance-checkpoint' : 'portal-attendance';
const identity = {
  entityKey: `student:${studentRef}`,
  unitKey: `portal-attendance:${assignmentId}:session:${sessionNumber}`,
  operationKey: `${prefix}:${recordId}:v1`,
  idempotencyKey: `${prefix}:${recordId}:enqueue:v1`
};
for (const [key, value] of Object.entries(identity)) {
  if (String(body[key] ?? '') !== value) throw new Error('ATTENDANCE_SYNC_IDENTITY_MISMATCH');
}
// Nhận liên kết đã lưu ở backend; commit thiếu đích/revision bị chặn trước Portal.
const targetSessionId = body.targetSessionId == null ? null : String(body.targetSessionId);
const bindingRevision = body.bindingRevision == null ? null : Number(body.bindingRevision);
const expectedScheduleFingerprint = body.expectedScheduleFingerprint == null ? null : String(body.expectedScheduleFingerprint);
if (targetSessionId !== null && !/^[1-9]\d*$/.test(targetSessionId)) throw new Error('ATTENDANCE_INVALID_BINDING');
if (bindingRevision !== null && (!Number.isSafeInteger(bindingRevision) || bindingRevision < 1)) throw new Error('ATTENDANCE_INVALID_BINDING');
if (commit && (!targetSessionId || !bindingRevision || !expectedScheduleFingerprint)) throw new Error('ATTENDANCE_BINDING_REQUIRED');
return [{ json: { assignmentId, studentRef, classId, studentId, sessionNumber, commit, teacherOverride,
  targetSessionId, bindingRevision, expectedScheduleFingerprint, ...identity } }];

// Nhận lịch và điểm danh đúng lớp; bỏ buổi hủy, kiểm đích đã khóa trước khi ghi.
// Trả quyết định hoặc yêu cầu đối soát; chỉ PUT khi phase commit có đủ liên kết.
const identity = $('Xác thực và khóa identity').first().json;
const root = $input.first()?.json ?? {};
const rows = Array.isArray(root) ? root : Array.isArray(root.data) ? root.data : Array.isArray(root.data?.data) ? root.data.data : [];
const meta = root.meta ?? root.data?.meta ?? {};
const raw = meta.class_sessions ?? root.class_sessions;
if (!Array.isArray(raw) || !raw.length || raw.length > 200) throw new Error('ATTENDANCE_SCHEDULE_INVALID');
const sessions = raw.map(s => ({ id: String(s.class_session_id ?? s.id ?? ''),
  // Portal trả giờ địa phương với T; Metabase trả dấu cách. Chuẩn hóa trước sắp thứ tự.
  startsAt: String(s.session_start_datetime ?? s.starts_at ?? s.start_time ?? '').replace('T', ' '),
  endsAt: String(s.session_end_datetime ?? s.ends_at ?? '').replace('T', ' '),
  status: s.status == null ? null : Number(s.status),
  classId: s.course_class_id == null ? identity.classId : String(s.course_class_id) }));
const ids = new Set(), starts = new Set();
for (const s of sessions) {
  if (!/^[1-9]\d*$/.test(s.id) || ![0, 1, 2].includes(s.status)
    || s.classId !== identity.classId || !/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(s.startsAt)
    || !Number.isFinite(Date.parse(s.startsAt.replace(' ', 'T') + 'Z'))
    || new Date(s.startsAt.replace(' ', 'T') + 'Z').toISOString().slice(0, 19) !== s.startsAt.replace(' ', 'T')
    || ids.has(s.id) || ([0, 1].includes(s.status) && starts.has(s.startsAt))) throw new Error('ATTENDANCE_SCHEDULE_AMBIGUOUS');
  ids.add(s.id);
  if ([0, 1].includes(s.status)) starts.add(s.startsAt);
}
sessions.sort((a, b) => a.startsAt.localeCompare(b.startsAt));
const valid = sessions.filter(s => [0, 1].includes(s.status));
const target = valid[identity.sessionNumber - 1];
if (!target && !identity.targetSessionId) throw new Error('ATTENDANCE_SESSION_NOT_FOUND');
const scheduleFingerprint = JSON.stringify([identity.classId, sessions.map(s => [s.id, s.startsAt, s.endsAt, s.status])]);
const pinnedId = identity.targetSessionId || target.id;
// Mã buổi do Progress Log xác nhận được giữ dù ngày mới làm thay đổi thứ tự.
// Ảnh lịch phải khớp để một job đang chờ không tự dùng lịch vừa thay đổi.
const pinnedSession = valid.find(s => s.id === pinnedId);
const confirmedPin = Boolean(identity.targetSessionId && pinnedSession
  && identity.expectedScheduleFingerprint === scheduleFingerprint);
const resolvedSessionId = confirmedPin ? pinnedId : target?.id ?? null;
const matches = rows.filter(r => String(r.student_id) === identity.studentId && String(r.class_session_id) === pinnedId);
if (matches.length > 1) throw new Error('ATTENDANCE_ROW_AMBIGUOUS');
const current = matches[0];
const currentStatus = current?.attendance_status == null || current?.attendance_status === '' ? null : Number(current.attendance_status);
let status = 'resolved', needsWrite = false;
// Bài đã ghi được đọc lại tại đích cũ kể cả lịch vừa đổi; không chuyển lịch sử.
if (currentStatus === 1) status = 'already_present';
else if (currentStatus !== null) status = 'conflict';
else if (identity.targetSessionId ? !confirmedPin : pinnedId !== target?.id) status = 'target_changed';
else if (identity.commit) {
  if (!identity.targetSessionId || !identity.bindingRevision || identity.expectedScheduleFingerprint !== scheduleFingerprint) status = 'target_changed';
  else { status = 'pending_write'; needsWrite = true; }
}
const safeNumber = value => {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < 1) throw new Error('ATTENDANCE_UNSAFE_ID');
  return number;
};
const requestBody = needsWrite ? { student_class_sessions: [{
  student_id: safeNumber(identity.studentId), class_session_id: safeNumber(pinnedId),
  attendance_status: 1, homework_status: current?.homework_status ?? null, note: current?.note ?? null
}] } : undefined;
return [{ json: { ...identity, targetSessionId: pinnedId, resolvedSessionId,
  scheduleFingerprint, sessionDate: (sessions.find(s => s.id === pinnedId) || target)?.startsAt.slice(0, 10) ?? null,
  status, needsWrite, requestBody } }];

// Nhận lịch và điểm danh đúng lớp; bỏ buổi hủy, kiểm đích đã khóa trước khi ghi.
// Trả quyết định hoặc yêu cầu đối soát; chỉ PUT khi phase commit có đủ liên kết.
const identity = $('Xác thực và khóa identity').first().json;
const root = $input.first()?.json ?? {};
const rows = Array.isArray(root) ? root : Array.isArray(root.data) ? root.data : Array.isArray(root.data?.data) ? root.data.data : [];
const meta = root.meta ?? root.data?.meta ?? {};
const raw = meta.class_sessions ?? root.class_sessions;
if (!Array.isArray(raw) || !raw.length || raw.length > 200) throw new Error('ATTENDANCE_SCHEDULE_INVALID');
const sessions = raw.map(s => ({ id: String(s.class_session_id ?? s.id ?? ''),
  // Portal trả giờ địa phương với T; Metabase trả dấu cách. Chuẩn hóa trước sắp thứ tự.
  startsAt: String(s.session_start_datetime ?? s.starts_at ?? s.start_time ?? '').replace('T', ' '),
  endsAt: String(s.session_end_datetime ?? s.ends_at ?? '').replace('T', ' '),
  status: s.status == null ? null : Number(s.status),
  classId: s.course_class_id == null ? identity.classId : String(s.course_class_id) }));
const ids = new Set(), starts = new Set();
for (const s of sessions) {
  if (!/^[1-9]\d*$/.test(s.id) || ![0, 1, 2].includes(s.status)
    || s.classId !== identity.classId || !/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(s.startsAt)
    || !Number.isFinite(Date.parse(s.startsAt.replace(' ', 'T') + 'Z'))
    || new Date(s.startsAt.replace(' ', 'T') + 'Z').toISOString().slice(0, 19) !== s.startsAt.replace(' ', 'T')
    || ids.has(s.id) || ([0, 1].includes(s.status) && starts.has(s.startsAt))) throw new Error('ATTENDANCE_SCHEDULE_AMBIGUOUS');
  ids.add(s.id);
  if ([0, 1].includes(s.status)) starts.add(s.startsAt);
}
sessions.sort((a, b) => a.startsAt.localeCompare(b.startsAt));
const valid = sessions.filter(s => [0, 1].includes(s.status));
const target = valid[identity.sessionNumber - 1];
if (!target && !identity.targetSessionId) throw new Error('ATTENDANCE_SESSION_NOT_FOUND');
const scheduleFingerprint = JSON.stringify([identity.classId, sessions.map(s => [s.id, s.startsAt, s.endsAt, s.status])]);

const written = $('Chọn đúng buổi và quyết định').first().json;
const saved = rows.find(row => String(row.student_id) === written.studentId
  && String(row.class_session_id) === written.targetSessionId);
if (!saved || Number(saved.attendance_status) !== 1) throw new Error('ATTENDANCE_SYNC_READBACK_FAILED');
return [{ json: { ...written, status: 'synced', needsWrite: false, requestBody: undefined,
  scheduleChanged: scheduleFingerprint !== written.scheduleFingerprint || !valid.some(s => s.id === written.targetSessionId) } }];

// Nhận quyết định/readback, trả đích thật cùng identity; không trả dữ liệu ghi Portal.
const value = $input.first().json;
return [{ json: { ok: true, status: value.status,
  entityKey: value.entityKey, unitKey: value.unitKey,
  operationKey: value.operationKey, idempotencyKey: value.idempotencyKey,
  classId: value.classId, studentId: value.studentId, sessionNumber: value.sessionNumber,
  targetSessionId: value.targetSessionId, resolvedSessionId: value.resolvedSessionId,
  bindingRevision: value.bindingRevision ?? null, scheduleFingerprint: value.scheduleFingerprint,
  sessionDate: value.sessionDate, scheduleChanged: Boolean(value.scheduleChanged) } }];
